from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parents[1]; D=ROOT/'dist'; D.mkdir(exist_ok=True)
base='https://fazalbinmahmood.com'
services=[('shopify-development','Shopify Development','Custom storefronts built around your products and the way your customers shop.','A store should be easy to use and easy to manage. I build Shopify storefronts with reusable sections, clear product information and a considered mobile experience.','We start with your catalogue, brand and customer journey. Then I turn the agreed design into a theme with editable sections, sensible defaults and focused functionality.','Theme development;Custom sections;Product templates;Mobile navigation;Launch checks'),('shopify-redesign','Shopify Redesign','A clearer shopping experience, from the first impression to the add-to-cart button.','A redesign starts with understanding what makes shopping difficult. The work can include navigation, product presentation, typography and the path from a collection to a purchase.','Before changing the design, we agree on the problems and priorities. After launch, real customer behaviour and analytics should guide the next improvements.','Storefront review;Mobile layouts;Collection pages;Product page design;Reusable design system'),('custom-functionality','Custom Shopify Functionality','Product personalisation and useful tools designed for the way your business works.','Some products need more than a standard product page. Personalised products, for example, need a clear input flow and a reliable way to carry a customer’s choices into the order.','I map the complete flow before building: inputs, previews, validation, cart data and error states. On mobile, the controls need to remain usable without hiding the product.','Product customisers;Custom inputs;Cart properties;Interactive previews;Practical testing'),('agency-partnerships','Agency Partnerships','Shopify design and development support for agencies delivering client projects.','I work through Xylo Solutions to help agencies turn approved designs into Shopify stores and custom sections. Clear scope and communication keep the handoff straightforward.','We agree on the deliverables, responsibilities and review points first. The handoff includes the theme code and notes on the parts your team will maintain.','Figma to Shopify;Theme builds;Section development;Responsive implementation;Project handoff')]
projects=[('nishani-store','Nishani','A personalised gifting storefront, designed around making a mug feel personal.','Shopify','Storefront','A personal ecommerce brand and a practical space to build a better customised-product experience. The work brings together product presentation, theme sections and mobile shopping.','The focus is a simple journey from choosing a design to personalising a product. The storefront needs to explain that journey before a customer commits to an order.'),('mug-customiser','Nishani Customiser','A guided personalisation flow with name input, design selection and a product preview.','Custom development','Personalisation','A guided Shopify product customiser for personalised mugs. Customers enter a name, select a design and review their choices before adding the product to the cart.','The implementation work includes character limits, optional text, preview positioning and a review step. Mobile usability matters at every stage, especially when the keyboard is open.'),('mug-studio','Nishani Mug Studio','An internal tool for previewing wrap artwork and preparing consistent product mockups.','Internal tool','Mug Studio','An internal artwork and mockup workflow for Nishani, built to make reviewing mug designs more consistent.','The tool focuses on wrap positioning, viewing angles, backgrounds and image exports. The design decisions are practical: keep the mug grounded, preserve the artwork and make the output useful for the store.'),('mobile-shopping','Mobile Shopping Experience','Navigation, readable layouts and product controls built for smaller screens.','Shopify','Mobile UX','Work on the Nishani storefront includes mobile navigation and a product customisation flow that can be used on smaller screens.','The key questions are simple: can customers find the product, understand it, enter their text and review their choices without losing their place? This is an overview of the work, not a measured conversion claim.'),('store-performance','Storefront Performance','Focused work on loading, fonts and the customer’s first interaction.','Optimisation','Performance','Performance improvements need to preserve the functionality that makes a store useful. Nishani provides a practical example of balancing a rich product experience with loading concerns.','The review includes fonts, images, scripts and when interactive features load. No performance score is claimed here; a published case study should include dated before-and-after measurements.'),('product-presentation','Product Presentation','Consistent artwork previews and product imagery for a personalised gifting brand.','Design systems','Product imagery','Personalised products need imagery that explains what the customer is choosing. The Nishani workflow considers artwork placement and repeatable product views.','A consistent presentation helps customers compare designs. Final project screenshots and documented outcomes will be added after the portfolio content review.')]
guides=[('shopify-redesign-checklist','A practical Shopify redesign checklist','Start with the shopping journey, then decide what needs to change.', [('Start with a problem','Write down the reason for the redesign. Is it difficult to find a product? Is the product information unclear? Are customers missing the personalisation controls? A useful brief connects every major design change to a real issue.'),('Map the important pages','Review the homepage, navigation, collections, search, product page and cart together. Improving one page while leaving the next step confusing can move the problem rather than solve it.'),('Design with real content','Use your longest product names, real photography, actual variants and complete delivery information. A layout that works only with short sample text is not ready to ship.'),('Check the whole journey','Test from the first visit through to the cart. Include sold-out variants, invalid inputs, long names and returning to a previous step. Keep a record of what you tested.'),('Measure after launch','Agree on the measures before launch and compare equivalent periods. Conversion changes have many possible causes, including traffic quality, pricing and promotions; do not credit the redesign without evidence.')]),('personalised-product-flow','Designing a personalised product flow','Make every choice understandable before the customer adds to cart.', [('Keep the steps clear','Separate entering a name, choosing a design and reviewing the product when doing so reduces confusion. Show progress without allowing the step indicator to dominate a small screen.'),('Validate before the cart','Show character limits and explain unsupported inputs next to the field. Keep the entered value when customers go back a step.'),('Treat previews carefully','A preview should reflect the chosen design and text. Account for long names and line wrapping, and explain any limitations that could affect the printed result.'),('Keep the order data complete','Every required personalisation choice must reach the order. Verify the cart and order data as well as the visible preview; a good-looking interface alone is not enough.')]),('mobile-store-review','How to review your store on mobile','A focused walkthrough for finding friction on a small screen.', [('Start with navigation','Check that the menu fits the screen, can be closed easily and does not leave the page permanently locked. Test nested categories with touch and a keyboard.'),('Use realistic inputs','Enter a long email address, a long product name and the maximum allowed personalisation text. Open the software keyboard and check that the next action remains reachable.'),('Read the product page','Price, options, availability and delivery information should be understandable without guesswork. Product images need to remain clear at the sizes customers actually see.'),('Use real devices too','Browser resizing is useful, but it is not the same as testing on a phone. Include real iOS and Android devices before a significant launch.')]),('store-speed-checklist','A practical storefront speed checklist','Keep useful features while reducing unnecessary work.', [('Review the largest assets','Start with images and video. Serve appropriately sized media, set image dimensions and avoid making below-the-fold media compete with the first screen.'),('Be selective with scripts','Review what each app or script does. Remove unused integrations carefully and check that remaining features still work after any change.'),('Keep typography focused','Use only the font families and weights the design needs. Avoid blocking readable content while a font downloads.'),('Measure consistently','Record the page, device profile and date. Repeat tests under comparable conditions and distinguish lab measurements from real-user data. A score is a diagnostic signal, not a guarantee of sales.')])]
def head(title,desc,path='/'):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | Fazal Bin Mahmood</title><meta name="description" content="{html.escape(desc)}"><link rel="canonical" href="{base}{path}"><meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{base}{path}"><meta name="theme-color" content="#000000"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>'''
nav='''<header class="header"><div class="container nav-row"><a class="signature" href="/" aria-label="Fazal Bin Mahmood home">Fazal Bin Mahmood</a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation"><details class="services-menu"><summary>Services</summary><div class="dropdown">'''+''.join(f'<a href="/services/{s[0]}/"><strong>{s[1]}</strong><span>{s[2]}</span></a>' for s in services)+'''</div></details><a href="/about/">About</a><a href="/#guides">eCommerce Guides</a><a href="/contact/">Contact</a><button class="search-toggle" aria-label="Search website"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/></svg></button></nav></div></header>'''
footer='''<footer><div class="container footer-grid"><div><a class="signature" href="/">Fazal Bin Mahmood</a><p>Shopify designer &amp; developer.<br>Founder of <a href="https://xylosolutions.com/">Xylo Solutions</a>.</p><a class="small-link" href="https://github.com/fazalbinmahmood1-netizen/Fazal-portfolio">Website source ↗</a></div><div><h2 class="footer-label">Featured links</h2>'''+''.join(f'<a class="footer-link" href="/services/{s[0]}/">{s[1]}</a>' for s in services)+'''<a class="footer-link" href="/#projects">Selected work</a><a class="footer-link" href="/about/">About Fazal</a></div><div><h2 class="footer-cta">Have a Shopify project in mind?<br>Let’s talk about your store.</h2><p>Share what you’re building and where you need help.</p><a class="button solid wide" href="/contact/">Get in touch</a></div></div><div class="copyright">© <span data-year>2026</span> Fazal Bin Mahmood. All rights reserved.</div></footer><dialog id="search-dialog" aria-labelledby="search-title"><button class="close-search" aria-label="Close search">×</button><h2 id="search-title">Search the website</h2><label for="search-input">Find a service, project or guide</label><input id="search-input" type="search" placeholder="Try Shopify or customiser" autocomplete="off"><div id="search-results" aria-live="polite"></div></dialog></body></html>'''
def save(path,content):
 f=D/path; f.parent.mkdir(parents=True,exist_ok=True);f.write_text(content)
def cover(i,title,category):
 colors=[('#e6ded5','#6c283c'),('#d5ddd6','#365144'),('#ddd9d5','#504a45'),('#dce0e6','#273a51'),('#e6e2d9','#454a34'),('#e8d9d7','#6c3c37')]; bg,fg=colors[i%6]
 # Authored graphic, not a screenshot or a claim about final client artwork.
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="800" height="520" viewBox="0 0 800 520"><rect width="800" height="520" fill="{bg}"/><rect x="120" y="75" width="560" height="370" rx="5" fill="#fff"/><path d="M120 113H680" stroke="{bg}" stroke-width="2"/><circle cx="141" cy="94" r="4" fill="{fg}"/><circle cx="156" cy="94" r="4" fill="{bg}"/><circle cx="171" cy="94" r="4" fill="{bg}"/><rect x="151" y="145" width="235" height="265" fill="{fg}"/><text x="175" y="270" fill="white" font-family="Georgia,serif" font-size="26">{html.escape(category)}</text><path d="M420 170H640M420 190H610M420 215H632" stroke="{bg}" stroke-width="8"/><rect x="420" y="250" width="170" height="35" rx="18" fill="{fg}"/><path d="M420 330H640M420 350H620M420 370H635" stroke="{bg}" stroke-width="5"/><text x="400" y="485" text-anchor="middle" fill="{fg}" font-family="Arial,sans-serif" font-size="14" letter-spacing="3">ILLUSTRATIVE PROJECT COVER</text></svg>'''
 save(f'assets/project-{i}.svg',svg)
 return f'<img src="/assets/project-{i}.svg" alt="Illustrative cover for {html.escape(title)}" width="800" height="520" loading="lazy">'
project_cards=''
for i,p in enumerate(projects):
 pic=cover(i,p[1],p[4]);project_cards+=f'<article class="project-card reveal"><a class="project-image" href="/projects/{p[0]}/">{pic}<span class="tag">{p[3]}</span></a><h3><a href="/projects/{p[0]}/">{p[1]}</a></h3><p>{p[2]}</p></article>'
guide_cards=''.join(f'<a class="guide-card reveal" href="/guides/{g[0]}/"><div class="guide-cover c{i}"><span>FIELD NOTES / 0{i+1}</span><strong>{["Shopify<br>Redesign","Personalised<br>Products","Mobile<br>Experience","Storefront<br>Speed"][i]}</strong><span aria-hidden="true">↗</span></div><h3>{g[1]}</h3></a>' for i,g in enumerate(guides))
index=head('Shopify Designer & Developer','Fazal Bin Mahmood, Shopify designer and developer and founder of Xylo Solutions. Custom stores, redesigns and product experiences.')+nav+'''<main id="main"><section class="hero"><div class="container"><div class="hero-copy reveal"><h1>Hi — I’m Fazal Bin Mahmood, the founder of <a href="https://xylosolutions.com/">Xylo Solutions</a> and hands-on Shopify designer &amp; developer.</h1><p>I work with brands and agencies to build thoughtful online stores, create better shopping experiences, and bring custom eCommerce ideas to life.</p><a class="button outline" href="/about/">Learn more</a></div><div class="brand-strip"><h2>DESIGN · DEVELOPMENT · ECOMMERCE</h2></div></div></section><section class="intro" id="services"><div class="container intro-grid"><div class="reveal"><h2>I work with brands to turn their ideas into considered, easy-to-use online stores.</h2><p>Through Xylo Solutions, I bring together <a href="/services/shopify-development/">Shopify development</a> and <a href="/services/shopify-redesign/">eCommerce design</a>. From a new storefront to a custom product experience, the focus is on making your website work better for your customers and your team.</p><a class="button solid" href="/contact/">Get in touch</a></div><div class="intro-note reveal"><div class="bubble"><p>A good storefront makes the next step feel obvious. Thoughtful design and dependable development should work together.</p></div><p class="attribution">Fazal Bin Mahmood <span>My approach to eCommerce</span></p></div></div></section><section class="projects" id="projects"><div class="container"><h2 class="center reveal">Featured Projects</h2><p class="section-note">Selected work and development notes from Nishani. Covers are illustrative.</p><div class="project-grid">'''+project_cards+'''</div><div class="center more"><a class="button outline" href="/projects/">View more projects</a></div></div></section><section class="testimonials" aria-labelledby="testimonials-heading"><div class="container"><h2 class="center" id="testimonials-heading">What Our Clients Say</h2><div class="quote-slider" aria-roledescription="carousel" aria-label="Client feedback layout preview"><div class="quote-panels"><div class="quote-panel" data-slide="0"><div class="bubble"><p class="eyebrow">CLIENT FEEDBACK · AWAITING APPROVED QUOTES</p><p>This space is reserved for a genuine client testimonial. The final quote will describe the project, the experience of working together, and the result in the client’s own words.</p><p>No sample review is presented as a real recommendation.</p></div><div class="quote-author"><span class="avatar" aria-hidden="true">FBM</span><p>Client name to be added<span>Company and role after approval</span></p></div></div><div class="quote-panel" data-slide="1" hidden><div class="bubble"><p class="eyebrow">CLIENT FEEDBACK · AWAITING APPROVED QUOTES</p><p>A second verified client quote will appear here. This preview demonstrates the slide transition and layout without borrowing another person’s testimonials.</p></div><div class="quote-author"><span class="avatar" aria-hidden="true">FBM</span><p>Client name to be added<span>Company and role after approval</span></p></div></div></div><div class="slider-controls"><button class="dot active" aria-label="Show testimonial 1" aria-pressed="true" data-to="0"></button><button class="dot" aria-label="Show testimonial 2" aria-pressed="false" data-to="1"></button></div></div></div></section><section class="guides" id="guides"><div class="container"><h2 class="center reveal">eCommerce Guides</h2><div class="guide-grid">'''+guide_cards+'''</div><div class="center more"><a class="button solid" href="/guides/">Read more posts</a></div></div></section></main>'''+footer
save('index.html',index)
search=[]; paths=['/']
def page(path,title,desc,body):
 save(path.strip('/')+'/index.html',head(title,desc,path)+nav+f'<main id="main" class="article-page"><article class="container article"><a class="back" href="/">← Back to home</a><h1>{title}</h1><p class="lead">{desc}</p>{body}</article></main>'+footer);paths.append(path);search.append({'title':title,'description':desc,'url':path})
page('/about/','About Fazal','Shopify designer, developer and founder of Xylo Solutions.','<h2>Design and development, together.</h2><p>I’m Fazal Bin Mahmood, based in Lahore, Pakistan. Through Xylo Solutions, I work on Shopify storefronts, redesigns and custom product experiences for brands and agencies.</p><p>I also build Nishani, a personalised gifting brand. Working on my own store gives me a practical view of the details behind the storefront: product artwork, customisation, mobile usability and day-to-day operations.</p><h2>How I approach a project</h2><p>I start with what the customer needs to do and what your team needs to manage. Then I connect the design, content and functionality into a clear shopping experience.</p><a class="button solid" href="/contact/">Discuss a project</a>')
page('/contact/','Let’s talk about your store.','Tell me what you’re building, what needs to improve, and when you’d like to launch.','<h2>Work with Xylo Solutions</h2><p>For project enquiries, visit the agency website and use its current contact options.</p><a class="button solid" href="https://xylosolutions.com/">Visit Xylo Solutions ↗</a><h2>A useful starting point</h2><ul><li>Your store URL or an overview of the new business</li><li>The design or development support you need</li><li>Your preferred timeline and project budget</li><li>Any reference websites or approved designs</li></ul><p>This portfolio does not currently collect contact submissions or newsletter subscriptions.</p>')
for s in services:
 page(f'/services/{s[0]}/',s[1],s[2],f'<h2>The work</h2><p>{s[3]}</p><h2>How we approach it</h2><p>{s[4]}</p><h2>Typical scope</h2><ul>'+''.join(f'<li>{x}</li>' for x in s[5].split(';'))+'</ul><p>Scope and timing are agreed for each project.</p><a class="button solid" href="/contact/">Discuss your project</a>')
for i,p in enumerate(projects):
 page(f'/projects/{p[0]}/',p[1],p[2],f'<img class="article-image" src="/assets/project-{i}.svg" alt="Illustrative project cover" width="800" height="520"><p class="caption">Illustrative cover. Final project screenshots are pending.</p><h2>Project overview</h2><p>{p[5]}</p><h2>Design and development focus</h2><p>{p[6]}</p><p class="content-note">Project notes, not a quantified results case study. Approved screenshots and evidence can be added here.</p><a class="button solid" href="/contact/">Discuss a similar project</a>')
for g in guides:
 page(f'/guides/{g[0]}/',g[1],g[2],''.join(f'<h2>{h}</h2><p>{p}</p>' for h,p in g[3])+'<p class="content-note">Written for this portfolio. Adapt this checklist to your store, and verify changes before publishing.</p>')
page('/projects/','Selected Work','Project notes from building a personalised ecommerce experience.','<div class="project-grid dark-cards">'+project_cards+'</div>')
page('/guides/','eCommerce Guides','Practical notes on designing and building Shopify stores.','<div class="guide-grid">'+guide_cards+'</div>')
save('assets/search.json',json.dumps(search))
save('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{base}{p}</loc></url>' for p in paths)+'</urlset>')
save('robots.txt',f'User-agent: *\nAllow: /\nSitemap: {base}/sitemap.xml\n')
save('404.html',head('Page not found','This page could not be found.')+nav+'<main id="main" class="article-page"><div class="container article"><h1>Page not found.</h1><p>The page may have moved. You can explore the portfolio from the homepage.</p><a class="button solid" href="/">Back to home</a></div></main>'+footer)
save('assets/favicon.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12"/><text x="32" y="42" fill="white" font-family="Arial" font-size="25" text-anchor="middle">FBM</text></svg>')
print(f'Generated {len(paths)} pages')
